from collections import deque

# BFS to find nodes at exactly depth 3
start = "c4ca4238a0"
target_depth = 3

# Track visited nodes to avoid cycles (but we track depth)
# We'll use a queue of (node, depth)
queue = deque([(start, 0)])
visited_at_depth = {start: 0}
nodes_at_depth = {0: {start}}

while queue:
    node, depth = queue.popleft()
    if depth >= target_depth:
        continue

    if node in graph:
        for neighbor in graph[node]:
            new_depth = depth + 1
            if neighbor not in visited_at_depth or visited_at_depth[neighbor] > new_depth:
                visited_at_depth[neighbor] = new_depth
                if new_depth not in nodes_at_depth:
                    nodes_at_depth[new_depth] = set()
                nodes_at_depth[new_depth].add(neighbor)
                queue.append((neighbor, new_depth))

print("Nodes at each depth:")
for d in sorted(nodes_at_depth.keys()):
    print(f"  Depth {d}: {sorted(nodes_at_depth[d])}")

print(f"\nNodes at exactly depth {target_depth}: {sorted(nodes_at_depth.get(target_depth, set()))}")
```

